<script>
(()=>{const shell=document.getElementById('ra-app');const button=document.getElementById('ra-collapse-btn');window.raToggleSidebar=()=>{if(innerWidth<1024){shell.classList.toggle('ra-mobile-nav-open');return;}shell.classList.toggle('ra-sidebar-mini');button.setAttribute('aria-expanded',String(!shell.classList.contains('ra-sidebar-mini')));};document.querySelectorAll('[data-ra-sidebar-toggle]').forEach(toggle=>toggle.addEventListener('click',window.raToggleSidebar));document.addEventListener('click',event=>{if(innerWidth<1024&&!event.target.closest('#ra-sidebar')&&!event.target.closest('[data-ra-sidebar-toggle]'))shell.classList.remove('ra-mobile-nav-open');});document.addEventListener('keydown',event=>{if(event.key==='Escape')shell.classList.remove('ra-mobile-nav-open');});})();
</script>
